from collections import deque
def comps(g, bg):
    R,C=len(g),len(g[0]); seen=[[False]*C for _ in range(R)]; out=[]
    for i in range(R):
        for j in range(C):
            if not seen[i][j] and g[i][j]!=bg:
                col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    r,c=q.popleft(); cells.append((r,c))
                    for dr,dc in((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<R and 0<=nc<C and not seen[nr][nc] and g[nr][nc]==col:
                            seen[nr][nc]=True; q.append((nr,nc))
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                out.append((col,len(cells),(min(rs),min(cs),max(rs),max(cs)),sorted(cells)))
    return out
